import { Card } from '@/components/ds/ui/card';
import { DotGrid } from '@/components/ds/ui/dot-grid';
import { Section } from '@/components/ds/ui/section';
import { SectionHeading } from '@/components/ds/ui/section-heading';

export type UseCaseGridProps = {
	title: string;
	highlight?: string;
	sub?: string;
	cases: { title: string; description: string; pattern: string[] }[];
};

export function UseCaseGrid({ title, highlight, sub, cases }: UseCaseGridProps) {
	return (
		<Section block="use-case-grid">
			<div className="flex flex-col gap-12">
				<SectionHeading title={title} highlight={highlight} sub={sub} />
				<div className="grid gap-4 md:grid-cols-2">
					{cases.slice(0, 6).map((c) => (
						<Card key={c.title}>
							<h3 className="text-h4">{c.title}</h3>
							<p className="text-body text-fg-muted">{c.description}</p>
							<div className="mt-auto flex justify-center rounded-card bg-tint p-6">
								<DotGrid pattern={c.pattern} size="sm" />
							</div>
						</Card>
					))}
				</div>
			</div>
		</Section>
	);
}
